-- ၁။ ကျောင်းသား Table
CREATE TABLE students ( id INT AUTO_INCREMENT PRIMARY KEY, first_name VARCHAR(50) NOT NULL, last_name VARCHAR(50) NOT NULL, email VARCHAR(100) UNIQUE, enrolled_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
); -- ၂။ ဆရာ Table
CREATE TABLE teachers ( id INT AUTO_INCREMENT PRIMARY KEY, first_name VARCHAR(50) NOT NULL, last_name VARCHAR(50) NOT NULL, subject VARCHAR(100)
); -- ၃။ သင်တန်း Table (Teachers Table နန့် ချိတ်ဆက်ထားသည်)
CREATE TABLE courses ( id INT AUTO_INCREMENT PRIMARY KEY, course_name VARCHAR(100) NOT NULL, teacher_id INT, FOREIGN KEY (teacher_id) REFERENCES teachers(id)
); -- ၄။ ကျောင်းအပ်မှတ်တမ်း Table (Students နန့် Courses ကို ချိတ်ဆက်သည်)
CREATE TABLE enrollments ( id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, course_id INT NOT NULL, grade DECIMAL(5, 2), FOREIGN KEY (student_id) REFERENCES students(id), FOREIGN KEY (course_id) REFERENCES courses(id)
);

