-- စျေးနှုန်း ၂၀ နန့် ၅၀ ကြားဟိသော ပစ္စည်းများ
SELECT name, price FROM products WHERE price BETWEEN 20 AND 50; -- ၂၀၂၅ ဖေဖော်ဝါရီလအတွင်း ဖြစ်သော အော်ဒါများ
SELECT * FROM orders WHERE order_date BETWEEN '2025-02-01' AND '2025-02-28';

168.body:
Table နှစ်ခုလုံးမာ ဒေတာ ကိုက်ညီမှု ဟိသော အတန်းများကိုသာ ထုတ်ပြပေးပါမည်။ SELECT orders.id AS order_id, customers.first_name, customers.last_name, orders.total_amount
FROM orders
INNER JOIN customers ON orders.customer_id = customers.id;

169.body:
SELECT o.id, c.first_name, c.last_name, o.total_amount
FROM orders o
INNER JOIN customers c ON o.customer_id = c.id;

