-- ညီမျှမှု စစ်ရန်
SELECT * FROM products WHERE price = 29.99; -- ကြီး / ငယ် စစ်ရန်
SELECT * FROM products WHERE price > 50;
SELECT * FROM products WHERE price <= 30; -- ကြားဟိ တန်ဖိုး စစ်ရန်
SELECT * FROM products WHERE price BETWEEN 20 AND 60; -- စာရင်းထဲမှ ရွေးရန်
SELECT * FROM customers WHERE city IN ('Yangon', 'Mandalay', 'Sittwe'); -- စာသား ပုံစံ ရှာရန် (LIKE)
SELECT * FROM customers WHERE email LIKE 'j%'; -- j ဖြင့် စသူများ
SELECT * FROM products WHERE name LIKE '%Pro%'; -- Pro ပါသူများ
SELECT * FROM customers WHERE city LIKE '%as'; -- as ဖြင့် ဆုံးသူများ -- AND / OR ပေါင်းစပ်ရန်
SELECT * FROM products WHERE price > 20 AND category = 'Electronics';
SELECT * FROM products WHERE category = 'Books' OR category = 'Sports'; -- NULL စစ်ရန်
SELECT * FROM customers WHERE phone IS NULL;
SELECT * FROM customers WHERE phone IS NOT NULL;
